select throws_ok($$select capture_document_link('99200000-0000-4000-8000-000000000001','99000000-0000-4000-8000-000000000001','{}',repeat('a',64),repeat('b',64))$$,'23514',null,'Missing artifacts rejected');
select lives_ok($$select capture_document_link('99200000-0000-4000-8000-000000000001','99000000-0000-4000-8000-000000000001',(select v::text from data where k='invoice_payload'),repeat('a',64),repeat('b',64))$$,'Invoice captured');
select lives_ok($$select capture_document_link('99200000-0000-4000-8000-000000000001','99000000-0000-4000-8000-000000000001',(select v::text from data where k='invoice_payload'),repeat('a',64),repeat('b',64))$$,'Exact capture retry resolves');
select throws_ok($$select capture_document_link('99200000-0000-4000-8000-000000000001','99000000-0000-4000-8000-000000000001',(select v::text from data where k='invoice_payload'),repeat('c',64),repeat('b',64))$$,'23505',null,'Token hash cannot be replaced');
select throws_ok($$select capture_document_link('99200000-0000-4000-8000-000000000002','99000000-0000-4000-8000-000000000001',(select jsonb_set(v,'{artifacts,1,content}','"YmFk"')::text from data where k='record_payload'),repeat('a',64),repeat('b',64))$$,'23514',null,'Corrupt original size/signature denied');
