select throws_ok($q$do $b$ begin alter table document_link_grants disable trigger document_link_immutable;update document_link_grants set expires_at=now()-interval '1 minute' where id='99200000-0000-4000-8000-000000000002';perform retrieve_document_link('99200000-0000-4000-8000-000000000002',repeat('a',64),0);end $b$ $q$,'42501',null,'Synthetic expired grant denied');
select throws_ok($q$do $b$ begin alter table document_link_payloads disable trigger document_link_immutable;update document_link_payloads set payload_text=replace(payload_text,'JVBERi10ZXN0','JVBERi1ldmls') where grant_id='99200000-0000-4000-8000-000000000002';perform retrieve_document_link('99200000-0000-4000-8000-000000000002',repeat('a',64),1);end $b$ $q$,'42501',null,'Frozen byte corruption denied before bytes');
