select throws_ok($q$do $b$ begin alter table document_link_payloads disable trigger document_link_immutable;update document_link_payloads set payload_text=replace(payload_text,'JVBERi10ZXN0','JVBERi1ldmls') where grant_id='99200000-0000-4000-8000-000000000002';perform read_document_link_artifact('99200000-0000-4000-8000-000000000002',1);end $b$ $q$,'42501',null,'Staff frozen-file inspection also rejects corrupted bytes');
