select is((select count(*)::integer from document_link_events where grant_id='99200000-0000-4000-8000-000000000002'),2,'Review and revoke retain append-only history');
select throws_ok($$update document_link_payloads set payload_text='{}' where grant_id='99200000-0000-4000-8000-000000000001'$$,'23514',null,'Frozen payload cannot be overwritten');
